import { fmt, n, q, num, L, U } from "./ee-shape.mjs";

const sqrt3 = Math.sqrt(3);
const vL = 400;
const vPh = vL / sqrt3;
const iLine = 10;
const sBal = sqrt3 * vL * iLine;
const pUnity = sBal;
const pf = 0.8;
const pPf = sBal * pf;
const qPf = sBal * 0.6;
const zPh = vPh / iLine;
const rPh = zPh * pf;
const xPh = zPh * 0.6;
const iDelta = 10;
const iDeltaLine = iDelta * sqrt3;
const pDelta = 3 * vL * iDelta;
const tanOverSqrt3 = 0.75 / sqrt3;
const wHi = (pPf * (1 + tanOverSqrt3)) / 2;
const wLo = (pPf * (1 - tanOverSqrt3)) / 2;

const inRe = 2.5;
const inIm = -2.5 * sqrt3;
const inMag = Math.hypot(inRe, inIm);
const openMag = 10;
const pRemain = 2 * vPh * 10;
const ang = Math.PI / 180;
const va = { re: vPh, im: 0 };
const vb = { re: vPh * Math.cos(-120 * ang), im: vPh * Math.sin(-120 * ang) };
const vc = { re: vPh * Math.cos(120 * ang), im: vPh * Math.sin(120 * ang) };
const ya = 0.1;
const yb = 0.1;
const yc = 0.05;
const ySum = ya + yb + yc;
const nRe = (va.re * ya + vb.re * yb + vc.re * yc) / ySum;
const nIm = (va.im * ya + vb.im * yb + vc.im * yc) / ySum;
const vn = Math.hypot(nRe, nIm);
const vHeavy = Math.hypot(va.re - nRe, va.im - nIm);
const vLight = Math.hypot(vc.re - nRe, vc.im - nIm);
const pf2 = 0.95;
const s2 = pPf / pf2;
const q2 = s2 * Math.sin(Math.acos(pf2));
const qc = qPf - q2;
const omega = 2 * Math.PI * 50;
const cWye = qc / (3 * vPh * vPh * omega);
const cDelta = qc / (3 * vL * vL * omega);

const ratio = 230 / 23;
const iSec = 10;
const iPri = iSec / ratio;
const reg = (23 - 22) / 22;
const pOut = 1000;
const pCore = 10;
const pCu = 20;
const eta = pOut / (pOut + pCore + pCu);
const zRefRe = 100 * 0.2;
const zRefIm = 100 * 0.5;
const zRefMag = Math.hypot(zRefRe, zRefIm);
const etaHalf = 500 / (500 + pCore + pCu / 4);

